'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const live=typeof google!=='undefined'&&google.script&&google.script.run;
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const money=c=>new Intl.NumberFormat('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2}).format(c/100);
const dateLabel=d=>new Date(d+'T12:00:00+07:00').toLocaleDateString('th-TH',{day:'numeric',month:'short'});
const monthLabel=m=>new Date(m+'-01T12:00:00+07:00').toLocaleDateString('th-TH',{month:'long',year:'numeric'});
const labels={overview:'ภาพรวม',accounts:'บัญชีทั้งหมด',transactions:'รายรับ / รายจ่าย',debts:'หนี้รายเดือน',calculator:'เครื่องคิดเลข',settings:'การตั้งค่า'};
let state=Finance.empty(),view='overview',month=today().slice(0,7),busy=false,demo=false,filterType='all',filterAccount='all',search='';
try{const stored=JSON.parse(localStorage.getItem('amocashs-v1')||'null');if(stored){state=stored.state;demo=stored.demo;}}catch{}
function rpc(method,...args){return new Promise((resolve,reject)=>{google.script.run.withSuccessHandler(resolve).withFailureHandler(reject)[method](...args);});}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4500);}
function save(){localStorage.setItem('amocashs-v1',JSON.stringify({state,demo}));}
async function commit(action,payload,date=today()){
 if(busy)throw new Error('กำลังบันทึก กรุณารอสักครู่');busy=true;
 const op={id:crypto.randomUUID(),action,payload,date,at:new Date().toISOString(),revision:state.revision};
 try{state=live?await rpc('mutate',op):Finance.apply(state,op);if(!live)save();render();toast(live?'บันทึกลง Google Sheet แล้ว':'บันทึกในอุปกรณ์นี้แล้ว');}
 catch(e){if(live){try{state=await rpc('getState');render();}catch{}}throw e;}finally{busy=false;}
}
const accountName=id=>state.accounts.find(a=>a.id===id)?.name||'ไม่พบบัญชี';
const options=()=>state.accounts.map(a=>`<option value="${esc(a.id)}">${esc(a.name)} · ฿${money(Finance.balance(state,a.id))}</option>`).join('');
const monthly=()=>state.transactions.filter(t=>t.date.startsWith(month));
const totals=()=>{const tx=monthly();return {income:tx.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0),expense:tx.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0),balance:state.accounts.reduce((s,a)=>s+Finance.balance(state,a.id),0)};};
const debts=()=>state.debts.filter(d=>d.start<=month);
const payment=d=>state.payments.find(p=>p.debt===d.id&&p.month===month);
function debtStatus(d){if(payment(d))return {text:'ชำระแล้ว',cls:'paid'};const last=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();const due=month+'-'+String(Math.min(d.day,last)).padStart(2,'0');return due<today()?{text:'เกินกำหนด',cls:'late'}:{text:'รอชำระ',cls:''};}
function heading(title,sub,action='transaction',button='เพิ่มรายการ'){return `<div class="page-title"><div><div class="eyebrow">${dateLabel(today())} ${new Date().toLocaleDateString('th-TH',{year:'numeric',timeZone:'Asia/Bangkok'})}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="toolbar">${['overview','transactions','debts'].includes(view)?`<input class="month-input" type="month" id="month" aria-label="เดือนที่แสดง" value="${month}">`:''}${action?`<button class="primary" data-action="${action}"><span class="plus">+</span>${button}</button>`:''}</div></div>`;}
function empty(title,action,label){return `<div class="empty"><div class="empty-icon">◌</div>${title}${action?`<br><button class="text-btn" data-action="${action}">${label} →</button>`:''}</div>`;}
function accountRow(a){return `<div class="account-row"><div class="bank ${a.color}">${esc(a.name.slice(0,2))}</div><div><div class="row-name">${esc(a.name)}</div><div class="row-sub">บัญชีส่วนตัว</div></div><div class="row-amount">฿${money(Finance.balance(state,a.id))}<small>ยอดเงินคงเหลือ</small></div></div>`;}
function txRows(tx){return tx.length?tx.map(t=>`<div class="transaction-row"><div class="tx-icon ${t.type}">${t.type==='income'?'↙':t.type==='transfer'?'⇄':'↗'}</div><div><div class="row-name">${esc(t.title)}</div><div class="row-sub">${esc(t.category)} · ${esc(accountName(t.account))}${t.to?' → '+esc(accountName(t.to)):''}</div></div><div class="tx-meta">${dateLabel(t.date)}</div><div class="row-amount ${t.type==='income'?'green-text':t.type==='expense'?'red-text':''}">${t.type==='income'?'+':t.type==='expense'?'−':''}฿${money(t.amount)}<small>${dateLabel(t.date)}</small></div></div>`).join(''):empty('ยังไม่มีรายการในเดือนนี้','transaction','บันทึกรายการแรก');}
function debtRows(list){return list.length?list.map(d=>{const status=debtStatus(d),p=payment(d);return `<div class="debt-row"><div class="debt-top"><div><div class="row-name">${esc(d.name)}</div><div class="row-sub">ครบกำหนดวันที่ ${d.day} ของเดือน</div></div><strong>฿${money(d.amount)}</strong></div><div class="debt-bottom"><span class="badge ${status.cls}">${p?'✓ ':''}${status.text}${p?' · '+dateLabel(p.date):''}</span>${!p?`<button class="pay-btn" data-pay="${esc(d.id)}">บันทึกชำระ ↗</button>`:`<span class="row-sub">${esc(accountName(p.account))}</span>`}</div></div>`;}).join(''):empty('ยังไม่มีหนี้รายเดือน','debt','เพิ่มรายการหนี้');}
function overview(){const t=totals(),ds=debts(),paid=ds.filter(payment).length,pending=ds.filter(d=>!payment(d)).reduce((s,d)=>s+d.amount,0);return heading('เงินของคุณ ในมุมที่ชัดเจน <span>✦</span>','ทุกบัญชี ทุกรายการ ดูแลได้ในที่เดียว')+`<section class="hero"><div class="hero-label">ยอดเงินคงเหลือทั้งหมด <span>${state.accounts.length} บัญชี</span></div><div class="hero-balance"><small>฿</small>${money(t.balance)}</div><div class="hero-foot"><div>รายรับเดือนนี้ <strong>+ ฿${money(t.income)}</strong></div><div>รายจ่ายเดือนนี้ <strong>− ฿${money(t.expense)}</strong></div></div><div class="hero-tag">◈ เงินทุกบัญชี ในที่เดียว</div></section><div class="stats"><div class="stat"><div class="stat-top">รายรับ <span class="stat-icon">↙</span></div><div class="stat-value"><span>฿</span>${money(t.income)}</div><div class="stat-bottom">${monthLabel(month)}</div></div><div class="stat"><div class="stat-top">รายจ่าย <span class="stat-icon red">↗</span></div><div class="stat-value"><span>฿</span>${money(t.expense)}</div><div class="stat-bottom">หักจากบัญชีที่บันทึก</div></div><div class="stat"><div class="stat-top">หนี้ที่รอชำระ <span class="stat-icon blue">◷</span></div><div class="stat-value"><span>฿</span>${money(pending)}</div><div class="stat-bottom">เหลือ ${ds.length-paid} รายการในเดือนนี้</div></div></div><div class="grid"><section class="panel"><div class="section-head"><div><h2>บัญชีของฉัน</h2><p>ยอดคงเหลือในทุกบัญชี</p></div><button class="text-btn" data-action="account">+ เพิ่มบัญชี</button></div>${state.accounts.length?state.accounts.map(accountRow).join(''):empty('เพิ่มบัญชีพร้อมยอดเงินเริ่มต้น','account','เพิ่มบัญชีแรก')}</section><section class="panel"><div class="section-head"><div><h2>หนี้ประจำเดือน</h2><p>${monthLabel(month)}</p></div><button class="text-btn" data-view="debts">ดูทั้งหมด ↗</button></div>${debtRows(ds.slice(0,3))}${ds.length?`<div class="progress"><div style="width:${paid/ds.length*100}%"></div></div><div class="progress-meta"><span>ชำระแล้ว ${paid} จาก ${ds.length} รายการ</span><span>${Math.round(paid/ds.length*100)}%</span></div>`:''}</section></div><section class="panel wide"><div class="section-head"><div><h2>รายการล่าสุด</h2><p>เล็กน้อยในแต่ละวัน รวมเป็นภาพใหญ่</p></div><button class="text-btn" data-view="transactions">ดูทั้งหมด ↗</button></div>${txRows(monthly().slice().reverse().slice(0,5))}</section>`;}
function accountsView(){return heading('บัญชีทั้งหมด','รวมยอดเงินจากทุกบัญชีของคุณ','account','เพิ่มบัญชี')+`<div class="account-cards">${state.accounts.map(a=>`<section class="account-card"><div class="account-row"><div class="bank ${a.color}">${esc(a.name.slice(0,2))}</div><div class="row-name">${esc(a.name)}</div></div><div class="stat-value"><span>฿</span>${money(Finance.balance(state,a.id))}</div><div class="row-sub">ยอดเริ่มต้น ฿${money(a.opening)}</div><button class="text-btn" data-account-history="${esc(a.id)}">ดูรายการบัญชีนี้ →</button></section>`).join('')||`<section class="panel">${empty('ยังไม่มีบัญชี','account','เพิ่มบัญชีแรก')}</section>`}</div>`;}
function filteredTransactions(){return monthly().filter(t=>(filterType==='all'||t.type===filterType)&&(filterAccount==='all'||t.account===filterAccount||t.to===filterAccount)&&t.title.toLowerCase().includes(search.toLowerCase())).slice().reverse();}
function transactionsView(){return heading('รายรับ / รายจ่าย','บันทึกทุกความเคลื่อนไหวของเงิน')+`<div class="filter-bar"><input id="search" aria-label="ค้นหารายการ" placeholder="ค้นหารายการ…" value="${esc(search)}"><select id="filter-type" aria-label="ประเภทรายการ"><option value="all">ทุกประเภท</option><option value="income">รายรับ</option><option value="expense">รายจ่าย</option><option value="transfer">โอนระหว่างบัญชี</option></select><select id="filter-account" aria-label="กรองบัญชี"><option value="all">ทุกบัญชี</option>${options()}</select><button class="secondary" data-action="export">ส่งออก CSV ↗</button></div><section class="panel" id="tx-list">${txRows(filteredTransactions())}</section>`;}
function debtsView(){return heading('หนี้รายเดือน','ชำระทีละรายการ ดูความคืบหน้าในแต่ละเดือน','debt','เพิ่มหนี้')+`<section class="panel">${debtRows(debts())}<p class="helper">การบันทึกชำระจะเพิ่มรายการรายจ่ายและหักเงินจากบัญชีที่เลือก พร้อมทำเครื่องหมายชำระแล้วเฉพาะเดือนนี้</p></section>`;}
function calculatorView(){return heading('เครื่องคิดเลข','คิดก่อนจ่าย แล้วบันทึกต่อได้เลย',null)+`<section class="panel calc"><div class="calc-display"><input id="expression" aria-label="สูตรคำนวณ" placeholder="0" inputmode="decimal"><div id="calc-result" class="calc-result">0.00</div></div><div class="calc-keys">${['C','(',')','⌫','7','8','9','÷','4','5','6','×','1','2','3','−','0','.','=','+'].map(k=>`<button data-key="${k}" class="${k==='='?'eq':/[÷×−+C⌫()]/.test(k)?'op':''}">${k}</button>`).join('')}</div><button class="primary full" style="margin-top:20px" data-action="use-calculator">นำยอดไปบันทึกรายการ ↗</button><p class="helper" style="margin:13px 0 0">รองรับวงเล็บและลำดับการคำนวณ</p></section>`;}
function settingsView(){return heading('ปรับให้เป็นคุณ','ตั้งค่าหน้าตาและดูสถานะการเชื่อมต่อ',null)+`<section class="panel settings-panel"><div class="setting-row"><div><h3>เลือกสไตล์ที่ชอบ</h3><p>สว่างในตอนกลางวัน สบายตาในตอนกลางคืน</p></div><div class="theme-switch"><button data-theme="light" class="${!document.body.classList.contains('dark')?'selected':''}">☀ สว่าง</button><button data-theme="dark" class="${document.body.classList.contains('dark')?'selected':''}">☾ มืด</button></div></div><div class="setting-row"><div><h3>Google Sheet</h3><p>${live?'เชื่อมต่อฐานข้อมูลผ่าน Google Apps Script':'โหมดออฟไลน์ · ข้อมูลบันทึกในเบราว์เซอร์นี้เท่านั้น'}</p><a href="https://docs.google.com/spreadsheets/d/16cELFn6q08ITvp8uT-3PKHfsAf-R7wIMNH6t6DgTd5U/edit" target="_blank" rel="noopener">เปิดฐานข้อมูล ↗</a></div><button class="secondary" data-action="refresh">รีเฟรช</button></div>${!live?`<div class="instructions"><p>สำหรับใช้งานข้อมูลจริง ให้เปิดแอปจาก Web App ของ Google Apps Script ที่ผูกกับชีตนี้</p><ol><li>เปิดส่วนขยาย → Apps Script ใน Google Sheet</li><li>ติดตั้งไฟล์ Code.gs และ Index.html จาก GitHub</li><li>ทำให้ใช้งานได้ → เว็บแอป → ดำเนินการในฐานะฉัน → สิทธิ์เฉพาะฉัน</li><li>เปิด URL ของ Web App เพื่อบันทึกและอ่านข้อมูลจากชีต</li></ol><a href="https://github.com/xserdevper-lab/A-mocashs" target="_blank" rel="noopener">ดูโค้ดและคู่มือบน GitHub ↗</a></div>`:''}<div class="setting-row"><div><h3>สำรองข้อมูล</h3><p>ดาวน์โหลดข้อมูลทุกบัญชี รายการ และประวัติชำระหนี้</p></div><button class="secondary" data-action="backup">ดาวน์โหลด JSON</button></div>${!live?`<div class="setting-row"><div><h3>ทดลองด้วยข้อมูลตัวอย่าง</h3><p>ใช้ได้เมื่อยังไม่มีข้อมูล และจะไม่ส่งเข้าชีต</p></div><button class="secondary" data-action="demo">${demo?'ล้างข้อมูลตัวอย่าง':'โหลดตัวอย่าง'}</button></div>`:''}</section>`;}
function render(){
 $('main').innerHTML=(demo?'<div class="demo-notice">◈ ข้อมูลตัวอย่างสำหรับทดลองใช้งาน · ไม่ใช่ยอดเงินจริง</div>':'')+({overview,accounts:accountsView,transactions:transactionsView,debts:debtsView,calculator:calculatorView,settings:settingsView}[view]())+(!live?`<div class="offline-note"><span>◌ ${demo?'โหมดทดลอง':'บันทึกในอุปกรณ์นี้'} · ยังไม่เชื่อม Google Sheet</span><button class="text-btn" data-view="settings">การเชื่อมต่อ ↗</button></div>`:'');
 $('crumb').textContent=labels[view];$('debt-count').textContent=debts().filter(d=>!payment(d)).length;$('status').textContent=live?'Google Sheet':'ออฟไลน์';$('status').classList.toggle('live',!!live);
 document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 if(view==='transactions'){$('filter-type').value=filterType;$('filter-account').value=filterAccount;}
}
function showModal(title,body){$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal').showModal();}
function form(body){return `<form id="entry-form">${body}<div class="form-error" id="form-error" role="alert"></div><button class="primary full" type="submit">บันทึก</button></form>`;}
function accountModal(){showModal('เพิ่มบัญชี',form(`<label>ชื่อบัญชี<input name="name" required maxlength="160" placeholder="เช่น กสิกรไทย / เงินสด"></label><label>ยอดเงินเริ่มต้น (บาท)<input name="opening" type="number" min="0" max="10000000000" step="0.01" required value="0"></label><label>สีบัญชี<select name="color"><option value="blue">ฟ้า</option><option value="green">เขียว</option><option value="purple">ม่วง</option><option value="orange">ส้ม</option></select></label>`));bindForm('account');}
function transactionModal(amount='',type='expense'){
 if(!state.accounts.length){toast('เพิ่มบัญชีก่อนบันทึกรายการ');accountModal();return;}
 showModal('บันทึกรายการ',`<div class="type-switch">${[['expense','รายจ่าย'],['income','รายรับ'],['transfer','โอนเงิน']].map(([t,l])=>`<button data-type="${t}" class="${type===t?'selected':''}">${l}</button>`).join('')}</div>`+form(`<input name="type" type="hidden" value="${type}"><label>จำนวนเงิน (บาท)<input id="tx-amount" name="amount" type="number" min="0.01" max="10000000000" step="0.01" value="${esc(amount)}" required placeholder="0.00"></label><label>รายละเอียด<input name="title" required maxlength="160" placeholder="เช่น อาหารกลางวัน"></label><label>${type==='transfer'?'บัญชีต้นทาง':'บัญชี'}<select name="account">${options()}</select></label>${type==='transfer'?`<label>บัญชีปลายทาง<select name="to">${options()}</select></label>`:''}<div class="form-grid"><label>หมวดหมู่<select name="category">${(type==='income'?['เงินเดือน','งานเสริม','อื่น ๆ']:type==='transfer'?['โอนเงิน']:['อาหาร','เดินทาง','ช้อปปิ้ง','ที่อยู่อาศัย','สุขภาพ','อื่น ๆ']).map(c=>`<option>${c}</option>`).join('')}</select></label><label>วันที่<input name="date" type="date" required value="${today()}"></label></div>`));bindForm('transaction');
}
function debtModal(){showModal('เพิ่มหนี้รายเดือน',form('<label>ชื่อรายการหนี้<input name="name" required maxlength="160" placeholder="เช่น ผ่อนรถ / บัตรเครดิต"></label><label>ยอดชำระต่อเดือน (บาท)<input name="amount" type="number" min="0.01" max="10000000000" step="0.01" required placeholder="0.00"></label><label>วันครบกำหนดของทุกเดือน<input name="day" type="number" min="1" max="31" required value="25"></label><p class="helper">สถานะชำระแยกตามเดือน เริ่มตั้งแต่เดือนปัจจุบัน วันที่ 29–31 จะใช้วันสุดท้ายเมื่อเดือนนั้นมีวันไม่ถึง</p>'));bindForm('debt');}
function payModal(id){if(!state.accounts.length){toast('เพิ่มบัญชีเพื่อชำระหนี้');return;}const d=state.debts.find(x=>x.id===id);showModal('บันทึกชำระหนี้',form(`<div class="helper">${esc(d.name)} · ${monthLabel(month)}<br>ยอดชำระ <strong>฿${money(d.amount)}</strong><br>นี่คือการบันทึกบัญชีการเงินส่วนตัว</div><input name="debt" type="hidden" value="${esc(id)}"><input name="month" type="hidden" value="${month}"><label>หักจากบัญชี<select name="account">${options()}</select></label><label>วันที่ชำระ<input name="date" type="date" required value="${today()}"></label>`));bindForm('pay');}
function bindForm(action){$('entry-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,button=f.querySelector('[type=submit]');button.disabled=true;const p=Object.fromEntries(new FormData(f));try{await commit(action,p,p.date||today());$('modal').close();}catch(e){$('form-error').textContent=e.message||'บันทึกไม่สำเร็จ';}finally{button.disabled=false;}};}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){const cell=v=>'"'+String(v).replace(/^[=+@-]/,'\'$&').replace(/"/g,'""')+'"';const rows=[['วันที่','ประเภท','รายละเอียด','หมวดหมู่','บัญชี','ปลายทาง','จำนวนบาท'],...filteredTransactions().map(t=>[t.date,t.type,t.title,t.category,accountName(t.account),t.to?accountName(t.to):'',t.amount/100])];download('amocashs-'+month+'.csv','\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function setTheme(theme){document.body.classList.toggle('dark',theme==='dark');localStorage.setItem('amocashs-theme',theme);$('theme').textContent=theme==='dark'?'☀':'☾';if(view==='settings')render();}
function loadDemo(){if(demo){state=Finance.empty();demo=false;save();render();toast('ล้างข้อมูลตัวอย่างแล้ว');return;}if(state.accounts.length||state.debts.length||state.transactions.length){toast('มีข้อมูลอยู่แล้ว ไม่สามารถแทนที่ด้วยตัวอย่าง');return;}state={revision:0,requests:[],accounts:[{id:'demo-cash',name:'เงินสด',opening:850000,color:'orange'},{id:'demo-kbank',name:'กสิกรไทย',opening:2450000,color:'green'},{id:'demo-scb',name:'ไทยพาณิชย์',opening:1285000,color:'purple'}],transactions:[{id:'demo-salary',type:'income',amount:3200000,account:'demo-kbank',to:'',title:'เงินเดือน',category:'เงินเดือน',date:month+'-01',at:''},{id:'demo-food',type:'expense',amount:18500,account:'demo-cash',to:'',title:'มื้อกลางวัน',category:'อาหาร',date:today(),at:''},{id:'demo-travel',type:'expense',amount:85000,account:'demo-kbank',to:'',title:'เติมน้ำมัน',category:'เดินทาง',date:today(),at:''},{id:'demo-home',type:'expense',amount:650000,account:'demo-kbank',to:'',title:'ชำระ ผ่อนบ้าน',category:'ชำระหนี้',date:today(),at:''}],debts:[{id:'demo-home-debt',name:'ผ่อนบ้าน',amount:650000,day:5,start:month},{id:'demo-car',name:'ผ่อนรถยนต์',amount:450000,day:15,start:month},{id:'demo-card',name:'บัตรเครดิต',amount:280000,day:25,start:month}],payments:[{id:'demo-home',debt:'demo-home-debt',month,account:'demo-kbank',amount:650000,date:today()}]};demo=true;save();view='overview';render();}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.view){view=b.dataset.view;history.replaceState(null,'','#'+view);render();window.scrollTo({top:0});}
 if(b.dataset.theme)setTheme(b.dataset.theme);
 if(b.dataset.accountHistory){filterAccount=b.dataset.accountHistory;view='transactions';render();}
 if(b.dataset.pay)payModal(b.dataset.pay);
 if(b.dataset.type){const amount=$('tx-amount').value;transactionModal(amount,b.dataset.type);}
 const action=b.dataset.action;
 if(action==='transaction')transactionModal();if(action==='account')accountModal();if(action==='debt')debtModal();if(action==='export')exportCSV();if(action==='backup')download('amocashs-backup-'+today()+'.json',JSON.stringify(state,null,2),'application/json');if(action==='demo')loadDemo();
 if(action==='refresh'){if(live){state=await rpc('getState');render();toast('โหลดข้อมูลล่าสุดแล้ว');}else toast('กำลังใช้ข้อมูลในอุปกรณ์นี้');}
 if(b.dataset.key){const input=$('expression'),k=b.dataset.key;if(k==='C'){input.value='';$('calc-result').textContent='0.00';}else if(k==='⌫')input.value=input.value.slice(0,-1);else if(k==='=')$('calc-result').textContent=Finance.calculate(input.value).toFixed(2);else input.value+=k==='−'?'-':k;}
 if(action==='use-calculator'){const result=Finance.calculate($('expression').value);if(result<=0)throw new Error('ยอดที่บันทึกต้องมากกว่า 0');transactionModal(result);}
 }catch(e){toast(e.message||'ดำเนินการไม่สำเร็จ');}});
document.addEventListener('change',e=>{if(e.target.id==='month'){if(!e.target.value)return;month=e.target.value;render();}if(e.target.id==='filter-type'){filterType=e.target.value;$('tx-list').innerHTML=txRows(filteredTransactions());}if(e.target.id==='filter-account'){filterAccount=e.target.value;$('tx-list').innerHTML=txRows(filteredTransactions());}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('tx-list').innerHTML=txRows(filteredTransactions());}});
document.addEventListener('keydown',e=>{if(e.target.id==='expression'&&e.key==='Enter'){e.preventDefault();try{$('calc-result').textContent=Finance.calculate(e.target.value).toFixed(2);}catch(err){toast(err.message);}}});
$('close-modal').onclick=()=>$('modal').close();$('theme').onclick=()=>setTheme(document.body.classList.contains('dark')?'light':'dark');
setTheme(localStorage.getItem('amocashs-theme')||'light');if(labels[location.hash.slice(1)])view=location.hash.slice(1);render();
if(live){demo=false;state=Finance.empty();render();rpc('getState').then(s=>{state=s;render();}).catch(e=>{toast('เชื่อม Google Sheet ไม่สำเร็จ: '+e.message);$('status').textContent='เชื่อมต่อไม่สำเร็จ';$('status').classList.remove('live');});}
